const store = new Map(); // key -> { value, storedAt }

async function swr(key, maxAge, revalidate) {
  const e = store.get(key);
  const now = Date.now();

  if (e && now - e.storedAt <= maxAge) {
    return e.value;                 // fresh
  }
  if (e) {
    // stale: serve stale, refresh in the background
    revalidate().then(v => store.set(key, { value: v, storedAt: Date.now() }));
    return e.value;
  }
  // cold: nothing cached yet
  const v = await revalidate();
  store.set(key, { value: v, storedAt: Date.now() });
  return v;
}
